// In-circuit CBOR parsing (Longfellow, Frigo & shelat, Section 4.3): the token stream of
// Algorithm 6 and the tree positions of Algorithm 8, for one CBOR data item.
//
// The tokenizer walks the item token by token: the j-th token starts at start[j] and the next one
// at start[j] + its length, so a byte is a token start iff it is some start[j]. The walk must
// reach the end of the item exactly; it then stays there.
// Alongside, a stack of open containers, (children left, offset) with the top first, gives each
// token its parent (the offset of the array, map or tag that contains it) and the number of the
// parent's children left after it, which is odd iff the token is a map key. A container that is
// the last child of its parent replaces the parent on the stack, so every entry has children left
// and a token that completes the top container pops exactly one entry. The four entries bound the
// nesting of containers that are not last children; the item must be exactly one CBOR item, so
// the stack only empties at its end.
// Only definite lengths are accepted, as mdoc requires, with string lengths and container counts
// below 65536. The parser bounds the number of tokens (T); the bound only affects completeness.

// Per-byte CBOR head tables, used as ROM lookups:
//   base[b]  token length when it does not depend on the following bytes, 0 if b cannot start a
//            token (indefinite lengths, and arrays and maps with 4- or 8-byte counts)
//   ext[b]   1 (resp. 2) if b is a byte/text string head with a 1-byte (resp. 2-byte) length
//   c0, c1, c2  number of children of the token: c0[b] + c1[b] * b1 + c2[b] * (256 * b1 + b2),
//            where b1, b2 are the bytes after the head (an array of n items has n children, a
//            map of n entries 2n, a tag 1, anything else 0)
fn tables() -> ([Field; 256], [Field; 256], [Field; 256], [Field; 256], [Field; 256]) {
    let mut base = [0; 256];
    let mut ext = [0; 256];
    let mut c0 = [0; 256];
    let mut c1 = [0; 256];
    let mut c2 = [0; 256];
    for b in 0..256 {
        let major = b / 32;
        let ai = b % 32;
        let is_str = (major == 2) | (major == 3);
        let is_container = (major == 4) | (major == 5);
        let head = if ai < 24 {
            1
        } else if ai == 24 {
            2
        } else if ai == 25 {
            3
        } else if ai == 26 {
            5
        } else {
            9
        };
        if (ai < 26) | (!is_str & !is_container & (ai < 28)) {
            base[b] = head as Field;
            if is_str & (ai < 24) {
                base[b] = (1 + ai) as Field;
            }
            if is_str & (ai == 24) {
                ext[b] = 1;
            }
            if is_str & (ai == 25) {
                ext[b] = 2;
            }
            if is_container {
                let m = if major == 4 { 1 } else { 2 };
                if ai < 24 {
                    c0[b] = (m * ai) as Field;
                }
                if ai == 24 {
                    c1[b] = m as Field;
                }
                if ai == 25 {
                    c2[b] = m as Field;
                }
            }
            if major == 6 {
                c0[b] = 1;
            }
        }
    }
    (base, ext, c0, c1, c2)
}

// The parsed item: for the j-th token, its offset, the offset of its parent (0 for the item
// itself), and the number of the parent's children left after it.
pub struct Tokens<let T: u32> {
    pub start: [u32; T],
    pub par: [Field; T],
    pub rem: [Field; T],
}

unconstrained fn find_token<let T: u32>(start: [u32; T], off: u32) -> u32 {
    let mut j = 0;
    for k in 0..T {
        if start[k] == off {
            j = k;
        }
    }
    j
}

impl<let T: u32> Tokens<T> {
    // Index of the token that starts at `off`; fails if no token starts there.
    pub fn at<let S: u32>(self, off: u32, msg: str<S>) -> u32 {
        // Safety: the hint is checked by the assertion that follows
        let j = unsafe { find_token(self.start, off) };
        assert(self.start[j] == off, msg);
        j
    }

    // Asserts that the j-th token is a key of a map.
    pub fn assert_key<let S: u32>(self, j: u32, msg: str<S>) {
        assert((self.rem[j] as u8) & 1 == 1, msg);
    }

    // Asserts that the j-th token is a key of the map at `parent`.
    pub fn assert_key_of<let S: u32>(self, j: u32, parent: Field, msg: str<S>) {
        assert(self.par[j] == parent, msg);
        self.assert_key(j, msg);
    }
}

// Parses buf[begin..end] as exactly one CBOR item of at most T tokens. buf must have two bytes
// after `end` (they may be anything) for the head lookahead.
pub fn parse<let N: u32, let T: u32>(buf: [u8; N], begin: u32, end: u32) -> Tokens<T> {
    let (base, ext, c0, c1, c2) = tables();
    let mut toks = Tokens { start: [0; T], par: [0; T], rem: [0; T] };
    // the item itself is the single child of a virtual container at offset 0
    let (mut n0, mut n1, mut n2, mut n3): (Field, Field, Field, Field) = (1, 0, 0, 0);
    let (mut s0, mut s1, mut s2, mut s3): (Field, Field, Field, Field) = (0, 0, 0, 0);
    let mut pos: u32 = begin;
    for j in 0..T {
        let at_end = pos == end;
        let active = 1 - at_end as Field;
        let r = n0 - 1;
        toks.start[j] = pos;
        toks.par[j] = s0;
        toks.rem[j] = r;
        let b = buf[pos] as u32;
        let b1 = buf[pos + 1] as Field;
        let b2 = buf[pos + 2] as Field;
        let len0 = base[b];
        assert((len0 != 0) | at_end, "Invalid CBOR token");
        // the stack is empty once the item is complete, which must happen at its end
        assert((n0 != 0) | at_end, "CBOR item is not well-formed");
        // ext = 1: + b1, ext = 2: + 256 * b1 + b2 (= 2 * b1 + 254 * b1 + b2)
        let e = ext[b];
        let len = len0 + e * b1 + e * (e - 1) * (254 * b1 + b2) / 2;
        pos += (active * len) as u32;
        // exactly one of push, replace, dec, pop is 1 for a token of the item:
        //   push     a container with siblings left: the parent stays below it
        //   replace  a container that is the last child: it takes the parent's entry
        //   dec      a leaf with siblings left
        //   pop      a leaf that completes the top container
        // (cont = push + replace)
        let children = c0[b] + c1[b] * b1 + c2[b] * (256 * b1 + b2);
        let cont = active * ((children != 0) as Field);
        let r_nz = (r != 0) as Field;
        let push = cont * r_nz;
        let dec = active * r_nz - push;
        let pop = active - cont - dec;
        assert(push * n3 == 0, "CBOR item is nested too deeply");
        let at = toks.start[j] as Field;
        let (m0, m1, m2, m3) = (
            n0 - dec + cont * (children - n0) + pop * (n1 - n0),
            n1 + push * (r - n1) + pop * (n2 - n1),
            n2 + push * (n1 - n2) + pop * (n3 - n2),
            n3 + push * (n2 - n3) - pop * n3,
        );
        let (t0, t1, t2, t3) = (
            s0 + cont * (at - s0) + pop * (s1 - s0),
            s1 + push * (s0 - s1) + pop * (s2 - s1),
            s2 + push * (s1 - s2) + pop * (s3 - s2),
            s3 + push * (s2 - s3) - pop * s3,
        );
        // materialize the state, so that its expressions do not grow across iterations
        n0 = m0;
        std::as_witness(n0);
        n1 = m1;
        std::as_witness(n1);
        n2 = m2;
        std::as_witness(n2);
        n3 = m3;
        std::as_witness(n3);
        s0 = t0;
        std::as_witness(s0);
        s1 = t1;
        std::as_witness(s1);
        s2 = t2;
        std::as_witness(s2);
        s3 = t3;
        std::as_witness(s3);
    }
    assert(pos == end, "CBOR item is not well-formed");
    assert(n0 == 0, "CBOR item is not well-formed");
    toks
}

// Asserts that `pattern` occurs at buf[off..].
pub fn check_at<let N: u32, let M: u32, let S: u32>(
    buf: [u8; N],
    off: u32,
    pattern: [u8; M],
    msg: str<S>,
) {
    for k in 0..M {
        assert(buf[off + k] == pattern[k], msg);
    }
}

// buf[off..off + M]
pub fn read_at<let N: u32, let M: u32>(buf: [u8; N], off: u32) -> [u8; M] {
    let mut out = [0; M];
    for k in 0..M {
        out[k] = buf[off + k];
    }
    out
}

52.source:
use std::hash::sha256_compression;

pub mod cbor;
pub mod predicates;

// ISO/IEC 18013-5 (9.1.2.4): the MSO digest of a data element is
//   h = H(IssuerSignedItemBytes), IssuerSignedItemBytes = #6.24(bstr .cbor IssuerSignedItem)
//   IssuerSignedItem = { "digestID": uint, "random": bstr, "elementIdentifier": tstr, "elementValue": any }
// The standard fixes neither the order of the four entries nor the length of random beyond a
// 16-byte minimum, and h is over the bytes exactly as the issuer encoded them. The circuits
// therefore receive IssuerSignedItemBytes as issued and parse it (parse_item): the four entries in
// any order, a random of MIN_RANDOM_LEN to MAX_RANDOM_LEN bytes, and items of up to 65535 bytes.
// The standard allows H = SHA-256, SHA-384 or SHA-512; SHA-512 is in ../sha512, and
// ../poseidon applies Poseidon to the same bytes for comparison, which no ISO issuer produces.

// A CBOR uint (digestID or an integer elementValue) takes at most 9 bytes
pub global MAX_UINT_LEN: u32 = 9;
pub global MIN_RANDOM_LEN: u32 = 16; // the minimum allowed by the standard
pub global MAX_RANDOM_LEN: u32 = 32;

// The four keys of IssuerSignedItem as CBOR text strings, each with a distinct first byte
global KEY_DIGEST_ID: [u8; 9] = [0x68, 0x64, 0x69, 0x67, 0x65, 0x73, 0x74, 0x49, 0x44];
global KEY_RANDOM: [u8; 7] = [0x66, 0x72, 0x61, 0x6e, 0x64, 0x6f, 0x6d];
global KEY_ELEMENT_ID: [u8; 18] = [
    0x71, 0x65, 0x6c, 0x65, 0x6d, 0x65, 0x6e, 0x74, 0x49, 0x64, 0x65, 0x6e, 0x74, 0x69, 0x66, 0x69,
    0x65, 0x72,
];
global KEY_VALUE: [u8; 13] =
    [0x6c, 0x65, 0x6c, 0x65, 0x6d, 0x65, 0x6e, 0x74, 0x56, 0x61, 0x6c, 0x75, 0x65];

// Decodes the CBOR unsigned integer (major type 0) at the start of field, in any of its encodings
// (1, 2, 3, 5 or 9 bytes, preferred or not; bytes after it are ignored). Returns the value, its
// encoded length and one-hot flags for the lengths 1, 2, 3, 5 and 9.
pub fn decode_uint<let N: u32>(field: [u8; N]) -> (u64, u32, [bool; 5]) {
    assert(N >= MAX_UINT_LEN);
    let b0 = field[0];
    assert(b0 >> 5 == 0, "Not a CBOR unsigned integer");
    let ai = b0 & 0x1f;
    let flags = [ai < 24, ai == 24, ai == 25, ai == 26, ai == 27];
    let lens = [1, 2, 3, 5, 9];
    let mut len = 0;
    for s in 0..5 {
        len += flags[s] as u32 * lens[s];
    }
    assert(len != 0, "Invalid CBOR integer head");
    // big-endian argument after the head, selected by length
    let mut v: Field = ai as Field;
    let mut arg: Field = 0;
    for i in 1..MAX_UINT_LEN {
        arg = arg * 256 + field[i] as Field;
        for s in 1..5 {
            if i == lens[s] - 1 {
                v += flags[s] as Field * (arg - ai as Field);
            }
        }
    }
    (v as u64, len, flags)
}

// Decodes the CBOR full-date (RFC 8943) at cbor[off..], tag 1004 over a 10-byte text string
// "YYYY-MM-DD", i.e. D9 03 EC 6A <date>, as the number YYYYMMDD
pub fn decode_full_date<let N: u32>(cbor: [u8; N], off: u32) -> u32 {
    let prefix = [0xD9, 0x03, 0xEC, 0x6A];
    for i in 0..4 {
        assert(cbor[off + i] == prefix[i], "Not a CBOR full-date");
    }
    assert((cbor[off + 8] == 45) & (cbor[off + 11] == 45), "Not a YYYY-MM-DD date");
    let mut date: u32 = 0;
    for i in [4, 5, 6, 7, 9, 10, 12, 13] {
        let c = cbor[off + i];
        assert((c >= 48) & (c <= 57), "Not a YYYY-MM-DD date");
        date = date * 10 + (c - 48) as u32;
    }
    date
}

// Decodes cbor, which must be exactly a CBOR text string of N < 24 bytes (head 0x60 + N)
pub fn decode_text<let N: u32, let M: u32>(cbor: [u8; M]) -> [u8; N] {
    assert(N < 24);
    assert(M == N + 1);
    assert(cbor[0] == 0x60 + N as u8, "Not a CBOR text string of the expected length");
    let mut out = [0; N];
    for i in 0..N {
        out[i] = cbor[1 + i];
    }
    out
}

// Decodes a digest as the MSO stores it in valueDigests: cbor must be exactly a CBOR byte string
// of N bytes, 24 <= N < 256 (head 58 NN)
pub fn decode_digest<let N: u32, let M: u32>(cbor: [u8; M]) -> [u8; N] {
    assert((N >= 24) & (N < 256));
    assert(M == N + 2);
    assert((cbor[0] == 0x58) & (cbor[1] == N as u8), "Not a CBOR byte string of the digest length");
    let mut out = [0; N];
    for i in 0..N {
        out[i] = cbor[2 + i];
    }
    out
}

// The parsed IssuerSignedItemBytes: the digestID, and where the elementValue is in the item.
pub struct Item {
    pub digest_id: u64,
    pub value_off: u32,
    pub value_len: u32,
}

// Size of the CBOR data item at buf[off..], computed outside the circuit (a hint)
unconstrained fn cbor_item_len<let N: u32>(buf: [u8; N], off: u32) -> u32 {
    let mut pos = off;
    let mut left: u32 = 1;
    for _ in 0..N {
        if (left != 0) & (pos + 2 < N) {
            let b = buf[pos] as u32;
            let (major, ai) = (b / 32, b % 32);
            let (arg, head) = if ai < 24 {
                (ai, 1)
            } else if ai == 24 {
                (buf[pos + 1] as u32, 2)
            } else if ai == 25 {
                (buf[pos + 1] as u32 * 256 + buf[pos + 2] as u32, 3)
            } else if ai == 26 {
                (0, 5)
            } else {
                (0, 9)
            };
            left -= 1;
            pos += head;
            if (major == 2) | (major == 3) {
                pos += arg;
            }
            if major == 4 {
                left += arg;
            }
            if major == 5 {
                left += 2 * arg;
            }
            if major == 6 {
                left += 1;
            }
        }
    }
    pos - off
}

// Offsets of the four entries (digestID, random, elementIdentifier, elementValue), their order in
// the item, and the length of the elementValue, computed outside the circuit (a hint)
unconstrained fn item_layout<let N: u32>(item: [u8; N], first: u32) -> ([u32; 4], [u32; 4], u32) {
    let mut offs = [0; 4];
    let mut order = [0; 4];
    let mut value_len = 0;
    let mut pos = first;
    for j in 0..4 {
        if pos < N {
            let b = item[pos];
            let k = if b == KEY_DIGEST_ID[0] {
                0
            } else if b == KEY_RANDOM[0] {
                1
            } else if b == KEY_ELEMENT_ID[0] {
                2
            } else {
                3
            };
            let key_len = [9, 7, 18, 13][k];
            offs[k] = pos;
            order[j] = k;
            let len = cbor_item_len(item, pos + key_len);
            if k == 3 {
                value_len = len;
            }
            pos += key_len + len;
        }
    }
    (offs, order, value_len)
}

// Parses IssuerSignedItemBytes, item[0..len], as issued: #6.24(bstr) over a map of the four
// entries in any order, with the elementIdentifier `element_id` (a text string shorter than 24
// bytes). Checks the tag and bstr head, the map head, each key, digestID (a CBOR uint), random (a
// bstr of MIN_RANDOM_LEN to MAX_RANDOM_LEN bytes) and the elementIdentifier, and that the entries
// are contiguous and fill the map. The elementValue is what remains; the caller checks that
// item[value_off..value_off + value_len] is exactly one CBOR item of the expected type, which makes
// the split of the item into entries unique.
pub fn parse_item<let N: u32, let E: u32>(item: [u8; N], len: u32, element_id: [u8; E]) -> Item {
    assert(E < 24);
    assert(len <= N, "IssuerSignedItemBytes exceeds the maximum size");
    // reads past the item (within the bound) are zeros
    let mut buf: [u8; N + 64] = [0; N + 64];
    for i in 0..N {
        buf[i] = item[i];
    }
    // D8 18, then the bstr head: 58 LL or 59 LL LL
    assert((buf[0] == 0xD8) & (buf[1] == 0x18), "Not IssuerSignedItemBytes (#6.24)");
    let short = buf[2] == 0x58;
    assert(short | (buf[2] == 0x59), "Not IssuerSignedItemBytes (bstr head)");
    let first = if short { 5 } else { 6 };
    let inner = if short {
        buf[3] as u32
    } else {
        buf[3] as u32 * 256 + buf[4] as u32
    };
    assert(inner == len - (first - 1), "IssuerSignedItemBytes length mismatch");
    assert(buf[first - 1] == 0xA4, "IssuerSignedItem is not a map of 4 entries");

    // Safety: the offsets, order and value length are checked below
    let (offs, order, value_len) = unsafe { item_layout(buf, first) };

    // the keys
    for k in 0..9 {
        assert(buf[offs[0] + k] == KEY_DIGEST_ID[k], "Invalid digestID key");
    }
    for k in 0..7 {
        assert(buf[offs[1] + k] == KEY_RANDOM[k], "Invalid random key");
    }
    for k in 0..18 {
        assert(buf[offs[2] + k] == KEY_ELEMENT_ID[k], "Invalid elementIdentifier key");
    }
    for k in 0..13 {
        assert(buf[offs[3] + k] == KEY_VALUE[k], "Invalid elementValue key");
    }
    // digestID: a CBOR uint
    let mut id_bytes = [0; MAX_UINT_LEN];
    for k in 0..MAX_UINT_LEN {
        id_bytes[k] = buf[offs[0] + 9 + k];
    }
    let (digest_id, id_len, _) = decode_uint(id_bytes);
    // random: a bstr of MIN_RANDOM_LEN to MAX_RANDOM_LEN bytes, head 40+n (n < 24) or 58 n
    let rh = buf[offs[1] + 7];
    let r_short = (rh >= 0x40) & (rh < 0x58);
    assert(r_short | (rh == 0x58), "random is not a CBOR byte string");
    let r_len = if r_short {
        (rh - 0x40) as u32
    } else {
        buf[offs[1] + 8] as u32
    };
    assert(
        (r_len >= MIN_RANDOM_LEN) & (r_len <= MAX_RANDOM_LEN),
        "random has an unsupported length",
    );
    let r_head = if r_short { 1 } else { 2 };
    // elementIdentifier: the text string element_id
    assert(buf[offs[2] + 18] == 0x60 + E as u8, "Wrong elementIdentifier");
    for k in 0..E {
        assert(buf[offs[2] + 19 + k] == element_id[k], "Wrong elementIdentifier");
    }
    // the entries in the hinted order are contiguous and fill the map
    let seg = [9 + id_len, 7 + r_head + r_len, 19 + E, 13 + value_len];
    for i in 0..4 {
        assert(order[i] < 4, "Invalid entry order");
        for j in 0..i {
            assert(order[i] != order[j], "Invalid entry order");
        }
    }
    let mut pos = first;
    for j in 0..4 {
        assert(offs[order[j]] == pos, "IssuerSignedItem entries are not contiguous");
        pos += seg[order[j]];
    }
    assert(pos == len, "IssuerSignedItem entries do not fill the item");
    Item { digest_id, value_off: offs[3] + 13, value_len }
}

// The elementValue of a parsed item as an array of V bytes (zeros after value_len)
pub fn item_value<let N: u32, let V: u32>(item: [u8; N], parsed: Item) -> [u8; V] {
    assert(parsed.value_len <= V, "elementValue exceeds the maximum size");
    let mut buf: [u8; N + V] = [0; N + V];
    for i in 0..N {
        buf[i] = item[i];
    }
    let mut out = [0; V];
    for i in 0..V {
        out[i] = (i < parsed.value_len) as u8 * buf[parsed.value_off + i];
    }
    out
}

// item[0..len] followed by the byte `marker` (0x80 for SHA-2 padding) and zeros
pub fn item_message<let N: u32>(item: [u8; N], len: u32, marker: Field) -> [Field; N + 1] {
    let mut msg = [0; N + 1];
    for i in 0..N {
        msg[i] = (i < len) as Field * item[i] as Field;
    }
    for i in 0..(N + 1) {
        msg[i] += (i == len) as Field * marker;
    }
    msg
}

// Merkle-Damgard padding: copies msg (which already holds the 0x80 byte) into BLOCKS blocks of
// B bytes and writes the length in bits into the last 8 bytes of the block where the message
// ends, given that the length field takes L bytes. Returns the padded message and a flag
// marking that last block.
pub fn md_pad<let N: u32, let B: u32, let L: u32, let BLOCKS: u32>(
    msg: [Field; N],
    len: u32,
) -> ([Field; B * BLOCKS], [bool; BLOCKS]) {
    assert(N <= B * BLOCKS);
    let mut padded = [0; B * BLOCKS];
    for i in 0..N {
        padded[i] = msg[i];
    }
    let bit_len: [u8; 8] = ((len * 8) as Field).to_be_bytes();
    let mut last = [false; BLOCKS];
    for b in 0..BLOCKS {
        last[b] = (len + 1 + L > B * b) & (len + 1 + L <= B * (b + 1));
        for j in 0..8 {
            padded[B * b + B - 8 + j] += last[b] as Field * bit_len[j] as Field;
        }
    }
    (padded, last)
}

// SHA-256(item[0..len]), hashing the padded item block by block
pub fn sha256_item_digest<let N: u32>(item: [u8; N], len: u32) -> [u8; 32] {
    let (msg, last): ([Field; 64 * ((N + 1 + 8 + 63) / 64)], [bool; (N + 1 + 8 + 63) / 64]) =
        md_pad::<_, 64, 8, _>(item_message(item, len, 0x80), len);

    let mut state: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab,
        0x5be0cd19,
    ];
    let mut digest_state = [0; 8];
    for b in 0..last.len() {
        let mut words = [0; 16];
        for w in 0..16 {
            let mut word = 0;
            for j in 0..4 {
                word = word * 256 + msg[64 * b + 4 * w + j];
            }
            words[w] = word as u32;
        }
        state = sha256_compression(words, state);
        for w in 0..8 {
            digest_state[w] += last[b] as Field * state[w] as Field;
        }
    }
    let mut out = [0; 32];
    for w in 0..8 {
        let bytes: [u8; 4] = digest_state[w].to_be_bytes();
        for j in 0..4 {
            out[4 * w + j] = bytes[j];
        }
    }
    out
}

// A 32-byte big-endian public input as a Field
pub fn field_from_be_bytes(bytes: [u8; 32]) -> Field {
    let mut f = 0;
    for i in 0..32 {
        f = f * 256 + bytes[i] as Field;
    }
    f
}

53.source:
// The predicates of the four test scenarios, shared by every variant. Each takes the
// elementValue exactly as the issuer encoded it (value[0..value_len], zero-padded to V bytes),
// checks that it is exactly one CBOR item of the element's type, and checks the predicate against
// the CBOR-encoded public parameters.
//
//   age        birth_date (full-date)              the holder is at least `threshold` years old today
//   rental     driving_privileges (array of maps)  a privilege of `category` issued on or before
//                                                  `held_since` and expiring on or after `return_date`
//   residence  resident_postal_code (text string)  the 5-digit ZIP code (ZIP or ZIP+4) is in
//                                                  [zip_min, zip_max]
//   veteran    veteran (uint, AAMVA namespace)      the value is 1
use crate::{cbor, decode_full_date, decode_uint, MAX_UINT_LEN};

// Maximum number of CBOR tokens of a driving_privileges value
pub global RENTAL_TOKENS: u32 = 64;

// birth_date: the holder turned `threshold` on or before today. Dates as YYYYMMDD: the holder is
// at least t years old iff birth + t * 10000 <= today.
pub fn age<let V: u32>(
    value: [u8; V],
    value_len: u32,
    today_cbor: [u8; 14],
    threshold_cbor: [u8; MAX_UINT_LEN],
) {
    assert(value_len == 14, "birth_date is not a CBOR full-date");
    let birth = decode_full_date(value, 0);
    let today = decode_full_date(today_cbor, 0);
    let (threshold, _, _) = decode_uint(threshold_cbor);
    assert(threshold < 200, "Invalid age threshold");
    assert(birth + threshold as u32 * 10000 <= today, "Age verification has failed");
}

// veteran: the uint 1
pub fn veteran<let V: u32>(value: [u8; V], value_len: u32) {
    let (v, len, _) = decode_uint(value);
    assert(len == value_len, "veteran is not a CBOR unsigned integer");
    assert(v == 1, "Veteran verification has failed");
}

// A 5-digit ASCII number at s[off..off + 5]
fn five_digits<let N: u32>(s: [u8; N], off: u32) -> u32 {
    let mut n: u32 = 0;
    for i in 0..5 {
        let c = s[off + i];
        assert((c >= 48) & (c <= 57), "Not a ZIP code");
        n = n * 10 + (c - 48) as u32;
    }
    n
}

// resident_postal_code: a text string holding a US ZIP code, "NNNNN" or ZIP+4 "NNNNN-NNNN", whose
// 5-digit ZIP is within [zip_min, zip_max] (each a 5-character text string)
pub fn residence<let V: u32>(
    value: [u8; V],
    value_len: u32,
    zip_min_cbor: [u8; 6],
    zip_max_cbor: [u8; 6],
) {
    assert(V >= 11);
    let n = value_len - 1;
    assert(value[0] == 0x60 + n as u8, "resident_postal_code is not a CBOR text string");
    assert((n == 5) | (n == 10), "Not a US ZIP code");
    let zip = five_digits(value, 1);
    if n == 10 {
        assert(value[6] == 45, "Not a US ZIP+4 code");
        for i in 7..11 {
            assert((value[i] >= 48) & (value[i] <= 57), "Not a US ZIP+4 code");
        }
    }
    assert((zip_min_cbor[0] == 0x65) & (zip_max_cbor[0] == 0x65), "Invalid ZIP range");
    let lo = five_digits(zip_min_cbor, 1);
    let hi = five_digits(zip_max_cbor, 1);
    assert((lo <= zip) & (zip <= hi), "Residence verification has failed");
}

// Keys of a DrivingPrivilege (ISO/IEC 18013-5 7.2.4) as CBOR text strings
global KEY_CATEGORY: [u8; 22] = [
    0x75, 0x76, 0x65, 0x68, 0x69, 0x63, 0x6c, 0x65, 0x5f, 0x63, 0x61, 0x74, 0x65, 0x67, 0x6f, 0x72,
    0x79, 0x5f, 0x63, 0x6f, 0x64, 0x65,
]; // "vehicle_category_code"
global KEY_ISSUE: [u8; 11] = [0x6a, 0x69, 0x73, 0x73, 0x75, 0x65, 0x5f, 0x64, 0x61, 0x74, 0x65]; // "issue_date"
global KEY_EXPIRY: [u8; 12] =
    [0x6b, 0x65, 0x78, 0x70, 0x69, 0x72, 0x79, 0x5f, 0x64, 0x61, 0x74, 0x65]; // "expiry_date"

// Offsets of the vehicle_category_code, issue_date and expiry_date keys of the privilege of
// `category`, computed outside the circuit (a hint)
unconstrained fn find_privilege<let N: u32, let T: u32>(
    buf: [u8; N],
    toks: cbor::Tokens<T>,
    category: [u8; 4],
) -> (u32, u32, u32) {
    let mut found = (0, 0, 0);
    for j in 0..T {
        let off = toks.start[j];
        let mut is_cat = off + 26 < N;
        if is_cat {
            for k in 0..22 {
                is_cat &= buf[off + k] == KEY_CATEGORY[k];
            }
            let n = (category[0] - 0x60) as u32;
            for k in 0..4 {
                if k <= n {
                    is_cat &= buf[off + 22 + k] == category[k];
                }
            }
        }
        if is_cat & ((toks.rem[j] as u8) & 1 == 1) {
            let map = toks.par[j];
            let mut issue = 0;
            let mut expiry = 0;
            for i in 0..T {
                let o = toks.start[i];
                if (toks.par[i] == map) & (o + 12 < N) {
                    let mut is_issue = true;
                    for k in 0..11 {
                        is_issue &= buf[o + k] == KEY_ISSUE[k];
                    }
                    let mut is_expiry = true;
                    for k in 0..12 {
                        is_expiry &= buf[o + k] == KEY_EXPIRY[k];
                    }
                    if is_issue {
                        issue = o;
                    }
                    if is_expiry {
                        expiry = o;
                    }
                }
            }
            found = (off, issue, expiry);
        }
    }
    found
}

// driving_privileges: an array of DrivingPrivilege maps, one of which has vehicle_category_code
// `category` (a text string of 1 to 3 characters), issue_date <= held_since and
// expiry_date >= return_date. The value is parsed in the circuit (cbor::parse), so the three
// entries are keys of the same map, an element of the array, and the map's keys may be in any
// order and include others (e.g. codes).
pub fn rental<let V: u32>(
    value: [u8; V],
    value_len: u32,
    category_cbor: [u8; 4],
    held_since_cbor: [u8; 14],
    return_date_cbor: [u8; 14],
) {
    assert(value_len <= V, "driving_privileges exceeds the maximum size");
    let mut buf: [u8; V + 40] = [0; V + 40];
    for i in 0..V {
        buf[i] = value[i];
    }
    let toks: cbor::Tokens<RENTAL_TOKENS> = cbor::parse(buf, 0, value_len);
    assert(buf[0] >> 5 == 4, "driving_privileges is not an array");
    let n = category_cbor[0] - 0x60;
    assert((n >= 1) & (n <= 3), "Invalid vehicle category");

    // Safety: the offsets are checked below
    let (cat, issue, expiry) = unsafe { find_privilege(buf, toks, category_cbor) };
    let jc = toks.at(cat, "No privilege of the category");
    cbor::check_at(buf, cat, KEY_CATEGORY, "No privilege of the category");
    for k in 0..4 {
        if k <= n as u32 {
            assert(buf[cat + 22 + k] == category_cbor[k], "No privilege of the category");
        }
    }
    // the privilege map is an element of the array, and the three keys are its keys
    let map = toks.par[jc];
    let map_off = map as u32;
    let jm = toks.at(map_off, "Invalid driving privilege");
    assert((map_off != 0) & (toks.par[jm] == 0), "Invalid driving privilege");
    assert(buf[map_off] >> 5 == 5, "Invalid driving privilege");
    toks.assert_key_of(jc, map, "Invalid driving privilege");
    let ji = toks.at(issue, "The privilege has no issue_date");
    cbor::check_at(buf, issue, KEY_ISSUE, "The privilege has no issue_date");
    toks.assert_key_of(ji, map, "The privilege has no issue_date");
    let je = toks.at(expiry, "The privilege has no expiry_date");
    cbor::check_at(buf, expiry, KEY_EXPIRY, "The privilege has no expiry_date");
    toks.assert_key_of(je, map, "The privilege has no expiry_date");

    let issued = decode_full_date(buf, issue + 11);
    let expires = decode_full_date(buf, expiry + 12);
    assert(issued <= decode_full_date(held_since_cbor, 0), "Privilege held for too short a time");
    assert(expires >= decode_full_date(return_date_cbor, 0), "Privilege expires before the return");
}

54.source:
// Noir port of the Longfellow-zk mdoc presentation circuit
// (Frigo & shelat, "Anonymous Credentials from ECDSA", IACR CiC 3(1), Algorithm 10).
//
// verify_mdoc proves, for public (PK_issuer, namespace, elementIdentifier, tr, now) and a private
// IssuerSignedItemBytes as issued, that
//
//   e1 = SHA256(Sig_structure(MSO))                       issuer-signed bytes
//   h2 = MSO[valueDigests][namespace][digestID]
//   h2 = SHA256(IssuerSignedItemBytes), whose digestID and elementIdentifier match
//   (dpk_x, dpk_y) = MSO[deviceKeyInfo][deviceKey][-2, -3]
//   validFrom < now < validUntil
//   p256.verify(sig_issuer, e1, PK_issuer)
//   p256.verify(sig_device, SHA256(tr || hdr), (dpk_x, dpk_y))
//
// and returns the parsed item, from which the caller reads the elementValue for its predicate.
// tr is the CBOR-encoded SessionTranscript and hdr the private COSE framing around it, i.e. the
// device signs Sig_structure(DeviceAuthenticationBytes) with
// DeviceAuthentication = ["DeviceAuthentication", tr, docType, DeviceNameSpacesBytes].
// The MSO paths are checked by parsing the MSO in the circuit (paper Section 4.3, with the parser
// of ../../iso/common/lib/src/cbor.nr): every field must start a CBOR token, and each token's
// parent container and key/value position are tracked, so a field is accepted only as the value
// of the key that the path names (e.g. validUntil is a key of the map that is the value of the
// top-level key validityInfo).
// The item is parsed and hashed with the same code as the ISO variants (../../iso/common/lib), so
// both approaches hash the attribute identically.
use iso::{cbor::{self, Tokens}, decode_uint, Item, MAX_UINT_LEN, parse_item, sha256_item_digest};
use sha256::sha256_var;

// 2231 = 35 * 64 - 9 bytes, the largest message that fits in 35 SHA-256 blocks
// (the MSO bound used in Longfellow's mdoc benchmark).
pub global MAX_SIGNED_LEN: u32 = 2231;
// Sig_structure = ["Signature1", h'A10126', h'', bstr(#6.24(bstr(MSO)))]
// 84 6A "Signature1" 43 A1 01 26 40 59 LL LL D8 18 59 MM MM <MSO>
global MSO_START: u32 = 25;

pub global DATE_LEN: u32 = 20; // tdate "YYYY-MM-DDTHH:MM:SSZ"
// now as a CBOR tdate, tag 0 over a 20-byte text string: C0 74 <date>
pub global NOW_CBOR_LEN: u32 = 2 + DATE_LEN;

// Device-signed Sig_structure = ["Signature1", h'A10126', h'', bstr(DeviceAuthenticationBytes)]
// 84 6A "Signature1" 43 A1 01 26 40 <bstr head> D8 18 <bstr head> 84 74 "DeviceAuthentication"
// <tr> 75 "org.iso.18013.5.1.mDL" D8 18 41 A0
pub global MAX_TR_LEN: u32 = 256;
global DA_PREFIX_LEN: u32 = 17;
global DA_TR_OFF: u32 = DA_PREFIX_LEN + 2 + 2 + 2 + 22; // with 1-byte bstr lengths
global DA_SUFFIX_LEN: u32 = 26;
pub global MAX_DA_LEN: u32 = DA_TR_OFF + 2 + MAX_TR_LEN + DA_SUFFIX_LEN;
global DA_ARRAY_HEAD: [u8; 22] = [
    0x84, 0x74, 0x44, 0x65, 0x76, 0x69, 0x63, 0x65, 0x41, 0x75, 0x74, 0x68, 0x65, 0x6e, 0x74, 0x69,
    0x63, 0x61, 0x74, 0x69, 0x6f, 0x6e,
]; // [ "DeviceAuthentication",
global DA_SUFFIX: [u8; DA_SUFFIX_LEN] = [
    0x75, 0x6f, 0x72, 0x67, 0x2e, 0x69, 0x73, 0x6f, 0x2e, 0x31, 0x38, 0x30, 0x31, 0x33, 0x2e, 0x35,
    0x2e, 0x31, 0x2e, 0x6d, 0x44, 0x4c, // "org.iso.18013.5.1.mDL"
    0xd8, 0x18, 0x41, 0xa0, // #6.24(bstr({}))
];

global VALUE_DIGESTS: [u8; 13] =
    [0x6c, 0x76, 0x61, 0x6c, 0x75, 0x65, 0x44, 0x69, 0x67, 0x65, 0x73, 0x74, 0x73]; // tstr "valueDigests"
global DEVICE_KEY_INFO: [u8; 14] =
    [0x6d, 0x64, 0x65, 0x76, 0x69, 0x63, 0x65, 0x4b, 0x65, 0x79, 0x49, 0x6e, 0x66, 0x6f]; // tstr "deviceKeyInfo"
global VALIDITY_INFO: [u8; 13] =
    [0x6c, 0x76, 0x61, 0x6c, 0x69, 0x64, 0x69, 0x74, 0x79, 0x49, 0x6e, 0x66, 0x6f]; // tstr "validityInfo"
global DEVICE_KEY: [u8; 18] = [
    0x69, 0x64, 0x65, 0x76, 0x69, 0x63, 0x65, 0x4b, 0x65, 0x79, // tstr "deviceKey"
    0xa4, 0x01, 0x02, 0x20, 0x01, 0x21, 0x58, 0x20, // {1: 2, -1: 1, -2: bstr(32) ...
];
global VALID_FROM: [u8; 12] =
    [0x69, 0x76, 0x61, 0x6c, 0x69, 0x64, 0x46, 0x72, 0x6f, 0x6d, 0xc0, 0x74];
global VALID_UNTIL: [u8; 13] =
    [0x6a, 0x76, 0x61, 0x6c, 0x69, 0x64, 0x55, 0x6e, 0x74, 0x69, 0x6c, 0xc0, 0x74];
global DOC_TYPE: [u8; 30] = [
    0x67, 0x64, 0x6f, 0x63, 0x54, 0x79, 0x70, 0x65, // tstr "docType"
    0x75, 0x6f, 0x72, 0x67, 0x2e, 0x69, 0x73, 0x6f, 0x2e, 0x31, 0x38, 0x30, 0x31, 0x33, 0x2e, 0x35,
    0x2e, 0x31, 0x2e, 0x6d, 0x44, 0x4c, // tstr "org.iso.18013.5.1.mDL"
];
global DIGEST_ALG: [u8; 24] = [
    0x6f, 0x64, 0x69, 0x67, 0x65, 0x73, 0x74, 0x41, 0x6c, 0x67, 0x6f, 0x72, 0x69, 0x74, 0x68, 0x6d,
    0x67, 0x53, 0x48, 0x41, 0x2d, 0x32, 0x35, 0x36,
]; // "digestAlgorithm": "SHA-256"

// Private witness shared by all scenarios
pub struct Mdoc<let N: u32> {
    pub signed: [u8; MAX_SIGNED_LEN], // issuer-signed Sig_structure, zero-padded
    pub signed_len: u32,
    pub issuer_sig: [u8; 64],
    pub item: [u8; N], // IssuerSignedItemBytes as issued, zero-padded
    pub item_len: u32,
    pub ns_off: u32, // CBOR offsets of the MSO fields, see credentials/inputs.py
    pub digest_off: u32,
    pub dk_off: u32,
    pub vf_off: u32,
    pub vu_off: u32,
    pub dt_off: u32,
    pub da_off: u32,
    pub device_sig: [u8; 64],
    pub device_msg: [u8; MAX_DA_LEN], // tr framed by hdr, zero-padded
    pub device_msg_len: u32,
}

// Asserts that `pattern` occurs at `buf[off..]`.
fn check_at<let N: u32, let M: u32>(buf: [u8; N], off: u32, pattern: [u8; M]) {
    for k in 0..M {
        assert(buf[off + k] == pattern[k], "MSO field does not match");
    }
}

fn read_at<let N: u32, let M: u32>(buf: [u8; N], off: u32) -> [u8; M] {
    let mut out = [0; M];
    for k in 0..M {
        out[k] = buf[off + k];
    }
    out
}

// Checks the head of a bstr of length `len` (< 65536) at `buf[off..]`, returns its size.
fn check_bstr_head<let N: u32>(buf: [u8; N], off: u32, len: u32) -> u32 {
    if len < 256 {
        assert(buf[off] == 0x58, "Invalid bstr length");
        assert(buf[off + 1] as u32 == len, "Invalid bstr length");
        2
    } else {
        assert(buf[off] == 0x59, "Invalid bstr length");
        assert((buf[off + 1] as u32) * 256 + (buf[off + 2] as u32) == len, "Invalid bstr length");
        3
    }
}

// Decodes a CBOR tdate, tag 0 over a 20-byte text string: C0 74 <YYYY-MM-DDTHH:MM:SSZ>
pub fn decode_tdate(cbor: [u8; NOW_CBOR_LEN]) -> [u8; DATE_LEN] {
    assert((cbor[0] == 0xc0) & (cbor[1] == 0x74), "Not a CBOR tdate");
    read_at(cbor, 2)
}

// YYYY-MM-DDTHH:MM:SSZ -> YYYYMMDDHHMMSS
fn tdate_to_u64(d: [u8; DATE_LEN]) -> u64 {
    let digits = [0, 1, 2, 3, 5, 6, 8, 9, 11, 12, 14, 15, 17, 18];
    let mut v: u64 = 0;
    for k in 0..14 {
        let c = d[digits[k]];
        assert((c >= 0x30) & (c <= 0x39), "Invalid tdate");
        v = v * 10 + ((c - 0x30) as u64);
    }
    v
}

// Maximum number of CBOR tokens in the MSO. The MSO of an mdoc is mostly digests, keys and
// dates, about 15 bytes per token (the test credentials have about 140 tokens in about 1570 bytes).
pub global MAX_TOKENS: u32 = 256;

// Asserts that `map` is the offset of a map that is the value of the top-level MSO key `key`,
// i.e. MSO[key] is that map.
fn assert_top_level_map<let M: u32, let S: u32>(
    toks: Tokens<MAX_TOKENS>,
    signed: [u8; MAX_SIGNED_LEN],
    map: Field,
    key: [u8; M],
    msg: str<S>,
) {
    let map_off = map as u32;
    assert(map_off >= MSO_START + M, msg);
    // the key is a whole token, so the token that follows it (its value) starts at map_off
    let key_off = map_off - M;
    let k = toks.at(key_off, msg);
    check_at(signed, key_off, key);
    toks.assert_key_of(k, MSO_START as Field, msg);
    assert(signed[map_off] >> 5 == 5, msg);
}

pub fn verify_mdoc<let S: u32, let E: u32, let N: u32>(
    issuer_pk_x: [u8; 32],
    issuer_pk_y: [u8; 32],
    tr: [u8; MAX_TR_LEN],
    tr_len: u32,
    now_cbor: [u8; NOW_CBOR_LEN],
    namespace: [u8; S], // CBOR text string
    element_id: [u8; E],
    mdoc: Mdoc<N>,
) -> Item {
    let Mdoc {
        signed,
        signed_len,
        issuer_sig,
        item,
        item_len,
        ns_off,
        digest_off,
        dk_off,
        vf_off,
        vu_off,
        dt_off,
        da_off,
        device_sig,
        device_msg,
        device_msg_len,
    } = mdoc;
    let now = decode_tdate(now_cbor);
    // 1. Sig_structure prefix and MSO length fields
    assert(signed_len <= MAX_SIGNED_LEN, "Signed MSO exceeds maximum size");
    assert(signed_len >= MSO_START + 256, "Signed MSO too small");
    let prefix: [u8; 18] = [
        0x84, 0x6a, 0x53, 0x69, 0x67, 0x6e, 0x61, 0x74, 0x75, 0x72, 0x65, 0x31, 0x43, 0xa1, 0x01,
        0x26, 0x40, 0x59,
    ];
    for k in 0..18 {
        assert(signed[k] == prefix[k], "Invalid Sig_structure");
    }
    assert(signed[20] == 0xd8, "Invalid Sig_structure");
    assert(signed[21] == 0x18, "Invalid Sig_structure");
    assert(signed[22] == 0x59, "Invalid Sig_structure");
    let len_field = signed_len as Field;
    assert(
        (signed[18] as Field) * 256 + (signed[19] as Field) == len_field - 20,
        "Invalid payload length",
    );
    assert(
        (signed[23] as Field) * 256 + (signed[24] as Field) == len_field - MSO_START as Field,
        "Invalid MSO length",
    );

    // 2. Issuer signature over e1 = SHA256(Sig_structure)
    let e1 = sha256_var(signed, signed_len as u64);
    assert(
        std::ecdsa_secp256r1::verify_signature(issuer_pk_x, issuer_pk_y, issuer_sig, e1),
        "Issuer signature verification has failed",
    );

    // 3. CBOR parsing of the MSO (paper Section 4.3): the token stream of Algorithm 6 and the
    //    tree positions of Algorithm 8.
    //    The tokenizer walks the MSO token by token: the j-th token starts at start[j] and the next
    //    one at start[j] + its length, so a byte is a token start iff it is some start[j]. The
    //    walk must reach signed_len exactly; it then stays there.
    //    Alongside, a stack of open containers, (children left, offset) with the top first, gives
    //    each token its parent and position, as the tree addresses of Algorithm 8. A container
    //    that is the last child of its parent replaces the parent on the stack, so every entry has
    //    children left and a token that completes the top container pops exactly one entry. The
    //    four entries bound the nesting of containers that are not last children; a standard mdoc
    //    MSO needs three (the MSO, valueDigests and a namespace map), one is spare.
    //    The MSO must be exactly one CBOR item: the stack only empties at signed_len.
    let mut buf: [u8; MAX_SIGNED_LEN + 3] = [0; MAX_SIGNED_LEN + 3];
    for i in 0..MAX_SIGNED_LEN {
        buf[i] = signed[i];
    }
    let toks: Tokens<MAX_TOKENS> = cbor::parse(buf, MSO_START, signed_len);
    assert(signed[MSO_START] >> 5 == 5, "MSO is not a map");

    // Every field read below must lie within the issuer-signed bytes: signed[signed_len..] is
    // private, unhashed witness, so a field there would not be covered by the issuer signature.
    // (Token starts are at least MSO_START, which bounds the offsets from below.)
    let field_end = |off: u32, len: u32| {
        assert(off + len <= signed_len, "MSO field outside the signed bytes");
    };

    // 4. h2 = MSO[valueDigests][namespace][digestID]
    let j = toks.at(ns_off, "Namespace is not a CBOR token");
    field_end(ns_off, S + 1);
    check_at(signed, ns_off, namespace);
    toks.assert_key(j, "Namespace is not in valueDigests");
    assert_top_level_map(
        toks,
        signed,
        toks.par[j],
        VALUE_DIGESTS,
        "Namespace is not in valueDigests",
    );
    let map_off = ns_off + S;
    assert(signed[map_off] >> 5 == 5, "Namespace value is not a map");
    let j = toks.at(digest_off, "Digest key is not a CBOR token");
    toks.assert_key_of(j, map_off as Field, "Digest is outside the namespace");
    // the entry's key must be the item's digestID; compare values, since the MSO and the item may
    // encode it differently
    let key: [u8; MAX_UINT_LEN] = read_at(signed, digest_off);
    let (id_mso, id_len, _) = decode_uint(key);
    let parsed = parse_item(item, item_len, element_id);
    let id_item = parsed.digest_id;
    assert(id_mso == id_item, "digestID mismatch");
    field_end(digest_off, id_len + 2 + 32);
    assert(signed[digest_off + id_len] == 0x58, "Digest is not a 32-byte bstr");
    assert(signed[digest_off + id_len + 1] == 0x20, "Digest is not a 32-byte bstr");
    let h2: [u8; 32] = read_at(signed, digest_off + id_len + 2);

    // 5. h2 = SHA256(IssuerSignedItemBytes), the item as issued (parsed above)
    let item_hash = sha256_item_digest(item, item_len);
    assert(item_hash == h2, "Attribute digest verification has failed");

    // 6. (dpk_x, dpk_y) = MSO[deviceKeyInfo][deviceKey][-2, -3], docType and digest algorithm
    let j = toks.at(dk_off, "deviceKey is not a CBOR token");
    field_end(dk_off, DEVICE_KEY.len() + 32 + 3 + 32);
    check_at(signed, dk_off, DEVICE_KEY);
    let dpk_x: [u8; 32] = read_at(signed, dk_off + 18);
    assert(signed[dk_off + 50] == 0x22, "Invalid deviceKey");
    assert(signed[dk_off + 51] == 0x58, "Invalid deviceKey");
    assert(signed[dk_off + 52] == 0x20, "Invalid deviceKey");
    let dpk_y: [u8; 32] = read_at(signed, dk_off + 53);
    toks.assert_key(j, "deviceKey is not in deviceKeyInfo");
    assert_top_level_map(
        toks,
        signed,
        toks.par[j],
        DEVICE_KEY_INFO,
        "deviceKey is not in deviceKeyInfo",
    );
    let j = toks.at(dt_off, "docType is not a CBOR token");
    field_end(dt_off, DOC_TYPE.len());
    check_at(signed, dt_off, DOC_TYPE);
    toks.assert_key_of(j, MSO_START as Field, "docType is not an MSO key");
    let j = toks.at(da_off, "digestAlgorithm is not a CBOR token");
    field_end(da_off, DIGEST_ALG.len());
    check_at(signed, da_off, DIGEST_ALG);
    toks.assert_key_of(j, MSO_START as Field, "digestAlgorithm is not an MSO key");

    // 7. MSO[validityInfo][validFrom] < now < MSO[validityInfo][validUntil]
    let jf = toks.at(vf_off, "validFrom is not a CBOR token");
    field_end(vf_off, VALID_FROM.len() + DATE_LEN);
    check_at(signed, vf_off, VALID_FROM);
    let ju = toks.at(vu_off, "validUntil is not a CBOR token");
    field_end(vu_off, VALID_UNTIL.len() + DATE_LEN);
    check_at(signed, vu_off, VALID_UNTIL);
    toks.assert_key(jf, "validFrom is not in validityInfo");
    assert_top_level_map(
        toks,
        signed,
        toks.par[jf],
        VALIDITY_INFO,
        "validFrom is not in validityInfo",
    );
    toks.assert_key_of(ju, toks.par[jf], "validUntil is not in validityInfo");
    let t_from = tdate_to_u64(read_at(signed, vf_off + 12));
    let t_until = tdate_to_u64(read_at(signed, vu_off + 13));
    let t_now = tdate_to_u64(now);
    assert(t_from < t_now, "Credential is not yet valid");
    assert(t_now < t_until, "Credential has expired");

    // 8. Device signature over SHA256(tr || hdr) under the hidden device key: device_msg must be
    //    the device-signed Sig_structure built around the public tr
    assert(tr_len <= MAX_TR_LEN, "SessionTranscript exceeds maximum size");
    let da_len = DA_ARRAY_HEAD.len() + tr_len + DA_SUFFIX_LEN;
    let dab_len = 2 + (if da_len < 256 { 2 } else { 3 }) + da_len;
    for k in 0..DA_PREFIX_LEN {
        assert(device_msg[k] == prefix[k], "Invalid device Sig_structure");
    }
    let mut off = DA_PREFIX_LEN;
    off += check_bstr_head(device_msg, off, dab_len);
    assert(device_msg[off] == 0xd8, "Invalid DeviceAuthenticationBytes");
    assert(device_msg[off + 1] == 0x18, "Invalid DeviceAuthenticationBytes");
    off += 2;
    off += check_bstr_head(device_msg, off, da_len);
    check_at(device_msg, off, DA_ARRAY_HEAD);
    off += DA_ARRAY_HEAD.len();
    for k in 0..MAX_TR_LEN {
        if k < tr_len {
            assert(device_msg[off + k] == tr[k], "SessionTranscript mismatch");
        }
    }
    check_at(device_msg, off + tr_len, DA_SUFFIX);
    assert(device_msg_len == off + tr_len + DA_SUFFIX_LEN, "Invalid device Sig_structure length");
    let e2 = sha256_var(device_msg, device_msg_len as u64);
    assert(
        std::ecdsa_secp256r1::verify_signature(dpk_x, dpk_y, device_sig, e2),
        "Device signature verification has failed",
    );
    parsed
}

58.source:
use std::hash::sha256_compression;
use std::runtime::is_unconstrained;

use constants::{
    BLOCK_BYTE_PTR, BLOCK_SIZE, HASH, INITIAL_STATE, INT_BLOCK, INT_BLOCK_SIZE, INT_SIZE,
    INT_SIZE_PTR, MSG_BLOCK, MSG_SIZE_PTR, STATE, TWO_POW_16, TWO_POW_24, TWO_POW_32, TWO_POW_8,
};

pub(crate) mod constants;
mod tests;

// Implementation of SHA-256 mapping a byte array of variable length to
// 32 bytes.

// Deprecated in favour of `sha256_var`
// docs:start:sha256
pub fn sha256<let N: u32>(input: [u8; N]) -> HASH
// docs:end:sha256
{
    digest(input)
}

// SHA-256 hash function
#[no_predicates]
pub fn digest<let N: u32>(msg: [u8; N]) -> HASH {
    sha256_var(msg, N as u64)
}

// Variable size SHA-256 hash
pub fn sha256_var<let N: u32>(msg: [u8; N], message_size: u64) -> HASH {
    let message_size = message_size as u32;
    assert(message_size <= N);

    if std::runtime::is_unconstrained() {
        // Safety: SHA256 is running as an unconstrained function.
        unsafe {
            __sha256_var(msg, message_size)
        }
    } else {
        let mut msg_block: MSG_BLOCK = [0; INT_BLOCK_SIZE];
        // Intermediate hash, starting with the canonical initial value
        let mut h: STATE = INITIAL_STATE;
        // Pointer into msg_block on a 64 byte scale
        let mut msg_byte_ptr = 0;
        let num_blocks = N / BLOCK_SIZE;
        for i in 0..num_blocks {
            let msg_start = BLOCK_SIZE * i;
            let (new_msg_block, new_msg_byte_ptr) =
                unsafe { build_msg_block(msg, message_size, msg_start) };

            if msg_start < message_size {
                msg_block = new_msg_block;
            }

            // Verify the block we are compressing was appropriately constructed
            let new_msg_byte_ptr = verify_msg_block(msg, message_size, msg_block, msg_start);
            if msg_start < message_size {
                msg_byte_ptr = new_msg_byte_ptr;
            }

            // If the block is filled, compress it.
            // An un-filled block is handled after this loop.
            if (msg_start < message_size) & (msg_byte_ptr == BLOCK_SIZE) {
                h = sha256_compression(msg_block, h);
            }
        }

        let modulo = N % BLOCK_SIZE;
        // Handle setup of the final msg block.
        // This case is only hit if the msg is less than the block size,
        // or our message cannot be evenly split into blocks.
        if modulo != 0 {
            let msg_start = BLOCK_SIZE * num_blocks;
            let (new_msg_block, new_msg_byte_ptr) =
                unsafe { build_msg_block(msg, message_size, msg_start) };

            if msg_start < message_size {
                msg_block = new_msg_block;
            }

            let new_msg_byte_ptr = verify_msg_block(msg, message_size, msg_block, msg_start);
            if msg_start < message_size {
                msg_byte_ptr = new_msg_byte_ptr;
                verify_msg_block_padding(msg_block, msg_byte_ptr);
            }
        }

        // If we had modulo == 0 then it means the last block was full,
        // and we can reset the pointer to zero to overwrite it.
        if msg_byte_ptr == BLOCK_SIZE {
            msg_byte_ptr = 0;
        }

        // Pad the rest such that we have a [u32; 2] block at the end representing the length
        // of the message, and a block of 1 0 ... 0 following the message (i.e. [1 << 7, 0, ..., 0]).
        // Here we rely on the fact that everything beyond the available input is set to 0.
        let index = msg_byte_ptr / INT_SIZE;
        msg_block[index] = set_item_byte_then_zeros(msg_block[index], msg_byte_ptr, 1 << 7);

        msg_byte_ptr = msg_byte_ptr + 1;
        let last_block = msg_block;

        // If we don't have room to write the size, compress the block and reset it.
        if msg_byte_ptr > MSG_SIZE_PTR {
            h = sha256_compression(msg_block, h);
            // `attach_len_to_msg_block` will zero out everything after the `msg_byte_ptr`.
            msg_byte_ptr = 0;
        }

        msg_block = unsafe { attach_len_to_msg_block(msg_block, msg_byte_ptr, message_size) };

        verify_msg_len(msg_block, last_block, msg_byte_ptr, message_size);

        hash_final_block(msg_block, h)
    }
}

// Variable size SHA-256 hash
unconstrained fn __sha256_var<let N: u32>(msg: [u8; N], message_size: u32) -> HASH {
    let num_full_blocks = message_size / BLOCK_SIZE;
    // Intermediate hash, starting with the canonical initial value
    let mut h: STATE = INITIAL_STATE;
    // Pointer into msg_block on a 64 byte scale
    for i in 0..num_full_blocks {
        let (msg_block, _) = build_msg_block(msg, message_size, BLOCK_SIZE * i);
        h = sha256_compression(msg_block, h);
    }

    // Handle setup of the final msg block.
    // This case is only hit if the msg is less than the block size,
    // or our message cannot be evenly split into blocks.
    let modulo = message_size % BLOCK_SIZE;
    let (mut msg_block, mut msg_byte_ptr): (INT_BLOCK, u32) = if modulo != 0 {
        let msg_start = BLOCK_SIZE * num_full_blocks;
        let (new_msg_block, new_msg_byte_ptr) = build_msg_block(msg, message_size, msg_start);
        (new_msg_block, new_msg_byte_ptr)
    } else {
        // If we had modulo == 0 then it means the last block was full,
        // and we can reset the pointer to zero to overwrite it.
        ([0; INT_BLOCK_SIZE], 0)
    };

    // Pad the rest such that we have a [u32; 2] block at the end representing the length
    // of the message, and a block of 1 0 ... 0 following the message (i.e. [1 << 7, 0, ..., 0]).
    // Here we rely on the fact that everything beyond the available input is set to 0.
    let index = msg_byte_ptr / INT_SIZE;
    msg_block[index] = set_item_byte_then_zeros(msg_block[index], msg_byte_ptr, 1 << 7);

    // If we don't have room to write the size, compress the block and reset it.
    let (h, mut msg_byte_ptr): (STATE, u32) = if msg_byte_ptr >= MSG_SIZE_PTR {
        // `attach_len_to_msg_block` will zero out everything after the `msg_byte_ptr`.
        (sha256_compression(msg_block, h), 0)
    } else {
        (h, msg_byte_ptr + 1)
    };
    msg_block = attach_len_to_msg_block(msg_block, msg_byte_ptr, message_size);

    hash_final_block(msg_block, h)
}

// Take `BLOCK_SIZE` number of bytes from `msg` starting at `msg_start`.
// Returns the block and the length that has been copied rather than padded with zeros.
unconstrained fn build_msg_block<let N: u32>(
    msg: [u8; N],
    message_size: u32,
    msg_start: u32,
) -> (MSG_BLOCK, BLOCK_BYTE_PTR) {
    let mut msg_block: MSG_BLOCK = [0; INT_BLOCK_SIZE];

    // We insert `BLOCK_SIZE` bytes (or up to the end of the message)
    let block_input = if message_size < msg_start {
        // This function is sometimes called with `msg_start` past the end of the message.
        // In this case we return an empty block and zero pointer to signal that the result should be ignored.
        0
    } else if message_size < msg_start + BLOCK_SIZE {
        message_size - msg_start
    } else {
        BLOCK_SIZE
    };

    // Figure out the number of items in the int array that we have to pack.
    // e.g. if the input is [0,1,2,3,4,5] then we need to pack it as 2 items: [0123, 4500]
    let int_input = (block_input + INT_SIZE - 1) / INT_SIZE;

    for i in 0..int_input {
        let mut msg_item: u32 = 0;
        // Always construct the integer as 4 bytes, even if it means going beyond the input.
        for j in 0..INT_SIZE {
            let k = i * INT_SIZE + j;
            let msg_byte = if k < block_input {
                msg[msg_start + k]
            } else {
                0
            };
            msg_item = lshift8(msg_item, 1) + msg_byte as u32;
        }
        msg_block[i] = msg_item;
    }

    // Returning the index as if it was a 64 byte array.
    // We have to project it down to 16 items and bit shifting to get a byte back if we need it.
    (msg_block, block_input)
}

// Verify the block we are compressing was appropriately constructed by `build_msg_block`
// and matches the input data. Returns the index of the first unset item.
// If `message_size` is less than `msg_start` then this is called with the old non-empty block;
// in that case we can skip verification, ie. no need to check that everything is zero.
fn verify_msg_block<let N: u32>(
    msg: [u8; N],
    message_size: u32,
    msg_block: MSG_BLOCK,
    msg_start: u32,
) -> BLOCK_BYTE_PTR {
    let mut msg_byte_ptr = 0;
    let mut msg_end = msg_start + BLOCK_SIZE;
    if msg_end > N {
        msg_end = N;
    }
    // We might have to go beyond the input to pad the fields.
    if msg_end % INT_SIZE != 0 {
        msg_end = msg_end + INT_SIZE - msg_end % INT_SIZE;
    }

    // Reconstructed packed item.
    let mut msg_item: u32 = 0;

    // Inclusive at the end so that we can compare the last item.
    let mut i: u32 = 0;
    for k in msg_start..=msg_end {
        if k % INT_SIZE == 0 {
            // If we consumed some input we can compare against the block.
            if (msg_start < message_size) & (k > msg_start) {
                assert_eq(msg_block[i], msg_item as u32);
                i = i + 1;
                msg_item = 0;
            }
        }
        // Shift the accumulator
        msg_item = lshift8(msg_item, 1);
        // If we have input to consume, add it at the rightmost position.
        if k < message_size & k < msg_end {
            msg_item = msg_item + msg[k] as u32;
            msg_byte_ptr = msg_byte_ptr + 1;
        }
    }

    msg_byte_ptr
}

// Verify the block we are compressing was appropriately padded with zeros by `build_msg_block`.
// This is only relevant for the last, potentially partially filled block.
fn verify_msg_block_padding(msg_block: MSG_BLOCK, msg_byte_ptr: BLOCK_BYTE_PTR) {
    // Check all the way to the end of the block.
    verify_msg_block_zeros(msg_block, msg_byte_ptr, INT_BLOCK_SIZE);
}

// Verify that a region of ints in the message block are (partially) zeroed,
// up to an (exclusive) maximum which can either be the end of the block
// or just where the size is to be written.
fn verify_msg_block_zeros(
    msg_block: MSG_BLOCK,
    mut msg_byte_ptr: BLOCK_BYTE_PTR,
    max_int_byte_ptr: u32,
) {
    // This variable is used to get around the compiler under-constrained check giving a warning.
    // We want to check against a constant zero, but if it does not come from the circuit inputs
    // or return values the compiler check will issue a warning.
    let zero = msg_block[0] - msg_block[0];

    // First integer which is supposed to be (partially) zero.
    let mut int_byte_ptr = msg_byte_ptr / INT_SIZE;

    // Check partial zeros.
    let modulo = msg_byte_ptr % INT_SIZE;
    if modulo != 0 {
        let zeros = INT_SIZE - modulo;
        let mask = if zeros == 3 {
            TWO_POW_24
        } else if zeros == 2 {
            TWO_POW_16
        } else {
            TWO_POW_8
        };
        assert_eq(msg_block[int_byte_ptr] % mask, zero);
        int_byte_ptr = int_byte_ptr + 1;
    }

    // Check the rest of the items.
    for i in 0..max_int_byte_ptr {
        if i >= int_byte_ptr {
            assert_eq(msg_block[i], zero);
        }
    }
}

// Verify that up to the byte pointer the two blocks are equal.
// At the byte pointer the new block can be partially zeroed.
fn verify_msg_block_equals_last(
    msg_block: MSG_BLOCK,
    last_block: MSG_BLOCK,
    mut msg_byte_ptr: BLOCK_BYTE_PTR,
) {
    // msg_byte_ptr is the position at which they are no longer have to be the same.
    // First integer which is supposed to be (partially) zero contains that pointer.
    let mut int_byte_ptr = msg_byte_ptr / INT_SIZE;

    // Check partial zeros.
    let modulo = msg_byte_ptr % INT_SIZE;
    if modulo != 0 {
        // Reconstruct the partially zero item from the last block.
        let last_field = last_block[int_byte_ptr];
        let mut msg_item: u32 = 0;
        // Reset to where they are still equal.
        msg_byte_ptr = msg_byte_ptr - modulo;
        for i in 0..INT_SIZE {
            msg_item = lshift8(msg_item, 1);
            if i < modulo {
                msg_item = msg_item + get_item_byte(last_field, msg_byte_ptr) as u32;
                msg_byte_ptr = msg_byte_ptr + 1;
            }
        }
        assert_eq(msg_block[int_byte_ptr], msg_item);
    }

    for i in 0..INT_SIZE_PTR {
        if i < int_byte_ptr {
            assert_eq(msg_block[i], last_block[i]);
        }
    }
}

// Set the rightmost `zeros` number of bytes to 0.
#[inline_always]
fn set_item_zeros(item: u32, zeros: u8) -> u32 {
    lshift8(rshift8(item, zeros), zeros)
}

// Replace one byte in the item with a value, and set everything after it to zero.
fn set_item_byte_then_zeros(msg_item: u32, msg_byte_ptr: BLOCK_BYTE_PTR, msg_byte: u8) -> u32 {
    let zeros = INT_SIZE - msg_byte_ptr % INT_SIZE;
    let zeroed_item = set_item_zeros(msg_item, zeros as u8);
    let new_item = byte_into_item(msg_byte, msg_byte_ptr);
    zeroed_item + new_item
}

// Get a byte of a message item according to its overall position in the `BLOCK_SIZE` space.
fn get_item_byte(mut msg_item: u32, msg_byte_ptr: BLOCK_BYTE_PTR) -> u8 {
    // How many times do we have to shift to the right to get to the position we want?
    let max_shifts = INT_SIZE - 1;
    let shifts = max_shifts - msg_byte_ptr % INT_SIZE;
    msg_item = rshift8(msg_item, shifts as u8);
    // At this point the byte we want is in the rightmost position.
    msg_item as u8
}

// Project a byte into a position in a field based on the overall block pointer.
// For example putting 1 into pointer 5 would be 100, because overall we would
// have [____, 0100] with indexes [0123,4567].
#[inline_always]
fn byte_into_item(msg_byte: u8, msg_byte_ptr: BLOCK_BYTE_PTR) -> u32 {
    let mut msg_item = msg_byte as u32;
    // How many times do we have to shift to the left to get to the position we want?
    let max_shifts = INT_SIZE - 1;
    let shifts = max_shifts - msg_byte_ptr % INT_SIZE;
    lshift8(msg_item, shifts as u8)
}

// Construct a field out of 4 bytes.
#[inline_always]
fn make_item(b0: u8, b1: u8, b2: u8, b3: u8) -> u32 {
    let mut item = b0 as u32;
    item = lshift8(item, 1) + b1 as u32;
    item = lshift8(item, 1) + b2 as u32;
    item = lshift8(item, 1) + b3 as u32;
    item
}

// Shift by 8 bits to the left between 0 and 4 times.
// Checks `is_unconstrained()` to just use a bitshift if we're running in an unconstrained context,
// otherwise multiplies by 256.
#[inline_always]
fn lshift8(item: u32, shifts: u8) -> u32 {
    if is_unconstrained() {
        // Brillig wouldn't shift 0<<4 without overflow.
        if shifts >= 4 {
            0
        } else {
            item << (8 * shifts)
        }
    } else {
        // We can do a for loop up to INT_SIZE or an if-else.
        if shifts == 0 {
            item
        } else if shifts == 1 {
            item * TWO_POW_8
        } else if shifts == 2 {
            item * TWO_POW_16
        } else if shifts == 3 {
            item * TWO_POW_24
        } else {
            // Doesn't make sense, but it's most likely called on 0 anyway.
            0
        }
    }
}

// Shift by 8 bits to the right between 0 and 4 times.
// Checks `is_unconstrained()` to just use a bitshift if we're running in an unconstrained context,
// otherwise divides by 256.
#[inline_always]
fn rshift8(item: u32, shifts: u8) -> u32 {
    if is_unconstrained() {
        item >> (8 * shifts)
    } else {
        // Division wouldn't work on `Field`.
        if shifts == 0 {
            item
        } else if shifts == 1 {
            item / TWO_POW_8
        } else if shifts == 2 {
            item / TWO_POW_16
        } else if shifts == 3 {
            item / TWO_POW_24
        } else {
            0
        }
    }
}

// Zero out all bytes between the end of the message and where the length is appended,
// then write the length into the last 8 bytes of the block.
unconstrained fn attach_len_to_msg_block(
    mut msg_block: MSG_BLOCK,
    mut msg_byte_ptr: BLOCK_BYTE_PTR,
    message_size: u32,
) -> MSG_BLOCK {
    // We assume that `msg_byte_ptr` is less than 57 because if not then it is reset to zero before calling this function.
    // In any case, fill blocks up with zeros until the last 64 bits (i.e. until msg_byte_ptr = 56).
    // There can be one item which has to be partially zeroed.
    let modulo = msg_byte_ptr % INT_SIZE;
    if modulo != 0 {
        // Index of the block in which we find the item we need to partially zero.
        let i = msg_byte_ptr / INT_SIZE;
        let zeros = INT_SIZE - modulo;
        msg_block[i] = set_item_zeros(msg_block[i], zeros as u8);
        msg_byte_ptr = msg_byte_ptr + zeros;
    }

    // The rest can be zeroed without bit shifting anything.
    for i in (msg_byte_ptr / INT_SIZE)..INT_SIZE_PTR {
        msg_block[i] = 0;
    }

    // Set the last two 4 byte ints as the first/second half of the 8 bytes of the length.
    let len = 8 * message_size;
    let len_bytes: [u8; 8] = (len as Field).to_be_bytes();
    msg_block[INT_SIZE_PTR] = (len_bytes[0] as u32) << 24
        | (len_bytes[1] as u32) << 16
        | (len_bytes[2] as u32) << 8
        | (len_bytes[3] as u32);

    msg_block[INT_SIZE_PTR + 1] = (len_bytes[4] as u32) << 24
        | (len_bytes[5] as u32) << 16
        | (len_bytes[6] as u32) << 8
        | (len_bytes[7] as u32);

    msg_block
}

// Verify that the message length was correctly written by `attach_len_to_msg_block`,
// and that everything between the byte pointer and the size pointer was zeroed,
// and that everything before the byte pointer was untouched.
fn verify_msg_len(
    msg_block: MSG_BLOCK,
    last_block: MSG_BLOCK,
    msg_byte_ptr: BLOCK_BYTE_PTR,
    message_size: u32,
) {
    // Check zeros up to the size pointer.
    verify_msg_block_zeros(msg_block, msg_byte_ptr, INT_SIZE_PTR);

    // Check that up to the pointer we match the last block.
    verify_msg_block_equals_last(msg_block, last_block, msg_byte_ptr);

    // We verify the message length was inserted correctly by reversing the byte decomposition.
    let mut reconstructed_len: u64 = 0;
    for i in INT_SIZE_PTR..INT_BLOCK_SIZE {
        reconstructed_len = reconstructed_len * TWO_POW_32;
        reconstructed_len = reconstructed_len + msg_block[i] as u64;
    }
    let len = 8 * message_size as u64;
    assert_eq(reconstructed_len, len);
}

// Perform the final compression, then transform the `STATE` into `HASH`.
fn hash_final_block(msg_block: MSG_BLOCK, mut state: STATE) -> HASH {
    let mut out_h: HASH = [0; 32]; // Digest as sequence of bytes
    // Hash final padded block
    state = sha256_compression(msg_block, state);

    // Return final hash as byte array
    for j in 0..8 {
        let h_bytes: [u8; 4] = (state[j] as Field).to_be_bytes();
        for k in 0..4 {
            out_h[4 * j + k] = h_bytes[k];
        }
    }

    out_h
}

mod equivalence_test {

    #[test]
    fn test_implementations_agree(msg: [u8; 100], message_size: u64) {
        let message_size = message_size % 100;
        // Safety: test function
        let unconstrained_sha = unsafe { super::__sha256_var(msg, message_size as u32) };
        let sha = super::sha256_var(msg, message_size);
        assert_eq(sha, unconstrained_sha);
    }
}
